package kome.common.data;

import java.util.Random;
import net.minecraft.nbt.NBTTagCompound;

/** Legal state transitions for the canonical Serf-to-Knight path. No world mutation occurs here. */
public final class KOMESerfKnightService {
    public static final int REQUIRED_ALIGNMENT = 150;
    public static final class Result { public final boolean success; public final String reason; public final String trialId; private Result(boolean success, String reason, String trialId) { this.success=success; this.reason=reason; this.trialId=trialId; } }
    private KOMESerfKnightService() { }
    private static Result ok() { return new Result(true, "", ""); }
    private static Result ok(String trialId) { return new Result(true, "", trialId); }
    private static Result reject(String reason) { return new Result(false, reason, ""); }
    public static Result setSerfdomMaster(KOMESerfKnightProgression state, KOMEProgressionNpcRef master) { if(state==null) return reject("Missing Serf-to-Knight state."); if(master==null || !master.isSet()) return reject("A Serfdom Master is required."); if(state.getSerfdomMaster().isSet()) return state.getSerfdomMaster().hasSameIdentity(master) ? ok() : reject("Changing the Serfdom Master is not supported."); state.setSerfdomMaster(master); return ok(); }
    public static Result assignDuty(KOMESerfKnightProgression state, KOMESerfKnightDutyType type) { return assignDuty(state, type, null); }
    public static Result assignDuty(KOMESerfKnightProgression state, KOMESerfKnightDutyType type, NBTTagCompound assignmentData) { if(state==null || type==null) return reject("A valid duty is required."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master must be selected first."); if(state.getPhase()!=KOMESerfKnightPhase.SERFDOM_DUTIES) return reject("Serfdom duties are no longer assignable."); if(state.getDuty(type).isAssigned()) return ok(); state.assignDuty(type, assignmentData); return ok(); }
    public static Result completeDuty(KOMESerfKnightProgression state, KOMESerfKnightDutyType type) { if(state==null || type==null) return reject("A valid duty is required."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master must be selected first."); if(!state.getDuty(type).isAssigned()) return reject("That duty has not been assigned."); if(state.getDuty(type).isCompleted()) return ok(); state.completeDuty(type); return ok(); }
    public static boolean allDutiesComplete(KOMESerfKnightProgression state) { if(state==null) return false; for(KOMESerfKnightDutyType type:KOMESerfKnightDutyType.values()) if(!state.getDuty(type).isCompleted()) return false; return true; }
    public static Result setProspectiveLiege(KOMESerfKnightProgression state, KOMEProgressionNpcRef liege) { if(state==null) return reject("Missing Serf-to-Knight state."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master must be selected first."); if(!allDutiesComplete(state)) return reject("All Serfdom duties must be complete before seeking a liege."); if(liege==null || !liege.isSet()) return reject("A prospective liege is required."); if(state.getTrialId().length()!=0 && !state.getProspectiveLiege().hasSameIdentity(liege)) return reject("The prospective liege cannot change after trial assignment."); state.setProspectiveLiege(liege); return ok(); }
    public static Result assignTrial(KOMESerfKnightProgression state, Random random) { if(state==null) return reject("Missing Serf-to-Knight state."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master must be selected first."); if(!allDutiesComplete(state)) return reject("All Serfdom duties must be complete before assigning a trial."); if(!state.getProspectiveLiege().isSet()) return reject("A prospective liege is required before assigning a trial."); if(state.getTrialId().length()!=0) return reject("An active Trial of Knighthood is already assigned."); if(random==null) return reject("A random source is required."); java.util.List<KOMESerfKnightTrial> trials=KOMESerfKnightTrial.all(); if(trials.isEmpty()) return reject("No Trials of Knighthood are registered."); KOMESerfKnightTrial trial=trials.get(random.nextInt(trials.size())); state.setTrial(trial.id); return ok(trial.id); }
    public static Result completeTrial(KOMESerfKnightProgression state) { if(state==null) return reject("Missing Serf-to-Knight state."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master must be selected first."); if(!allDutiesComplete(state)) return reject("All Serfdom duties must be complete before completing a trial."); if(!state.getProspectiveLiege().isSet()) return reject("A prospective liege is required."); if(KOMESerfKnightTrial.forId(state.getTrialId())==null) return reject("No valid Trial of Knighthood is assigned."); if(state.isTrialCompleted()) return ok(); state.setTrialCompleted(); return ok(); }
    public static Result recordPartingGift(KOMESerfKnightProgression state) { if(state==null) return reject("Missing Serf-to-Knight state."); if(!state.getSerfdomMaster().isSet()) return reject("A Serfdom Master is required for the parting gift."); if(!allDutiesComplete(state) || !state.getProspectiveLiege().isSet() || KOMESerfKnightTrial.forId(state.getTrialId())==null) return reject("A valid completed Serfdom and Trial path is required for the parting gift."); if(!state.isTrialCompleted()) return reject("The Trial of Knighthood must be complete before the parting gift."); if(state.hasPartingGift()) return ok(); state.setPartingGiftReceived(); return ok(); }
    public static boolean canPromote(KOMESerfKnightProgression state, double currentFactionAlignment) { return promotionReason(state, currentFactionAlignment).length()==0; }
    public static String promotionReason(KOMESerfKnightProgression state, double currentFactionAlignment) { if(state==null) return "Missing Serf-to-Knight state."; if(state.isPromoted()) return "Knight promotion is already complete."; if(currentFactionAlignment < REQUIRED_ALIGNMENT) return "Requires at least 150 positive faction alignment."; if(!state.getSerfdomMaster().isSet()) return "A Serfdom Master is required."; if(!allDutiesComplete(state)) return "All Serfdom duties must be complete."; if(!state.getProspectiveLiege().isSet()) return "A prospective liege is required."; if(state.getTrialId().length()==0) return "A Trial of Knighthood is required."; if(!state.isTrialCompleted()) return "The Trial of Knighthood must be complete."; if(!state.hasPartingGift()) return "The Serfdom Master parting gift is required."; return ""; }
    public static Result markPromoted(KOMESerfKnightProgression state, double currentFactionAlignment) { if(state != null && state.isPromoted()) return ok(); String reason=promotionReason(state,currentFactionAlignment); if(reason.length()!=0) return reject(reason); state.setPromoted(); return ok(); }
}
